// The yoke's own web page, served as /0.js into an otherwise empty page; see docs/reference/firmware.md.
"use strict";

// As in the core's constants.h.
const WAYS = 12;
const OVER_RANGE_A = 30;
const INSTALL_S = 3600;

// ── Model: entities by name, from the /events stream ──

function newStore() {
  return new Map();
}

// A state message's id is "domain/Name". Entities are found by name, so a renamed one shows as a
// missing reading rather than breaking the page.
function receive(store, msg, now) {
  const name = msg.id.slice(msg.id.indexOf("/") + 1);
  store.set(name, { value: msg.value, at: now });
}

// "3, 4, 7, 11" or "None" into [3, 4, 7, 11].
function wayList(text) {
  return !text || text === "None" ? [] : text.split(",").map(Number).filter(Boolean);
}

// The ways with one kind of fault, from a part such as "Ways 3, 7 blown" or "Way 9 over range".
function waysWith(faults, kind) {
  const out = [];
  for (const part of faults) {
    const m = /^Ways? ([\d, ]+) (.+)$/.exec(part);
    if (m && m[2] === kind) out.push(...wayList(m[1]));
  }
  return out;
}

// A way carries current while live, or while over range, which may be a sensor stuck at a rail.
const flowing = (w) => w && (w.state === "live" || w.state === "range");

function readWay(store, n, overRange, notZeroed) {
  const val = (item) => store.get(`Way ${n}: ${item}`)?.value;
  if (val("Live") == null && val("Blown Fuse") == null && val("Current") == null) return null;
  const live = val("Live") === true;
  const blown = val("Blown Fuse") === true;
  const state = overRange.includes(n) ? "range" : blown ? "blown" : live ? "live" : "empty";
  return {
    n, state, live, blown,
    unzeroed: notZeroed.includes(n),
    current: val("Current"),
    power: val("Power"),
    energy: val("Energy"),
    zero: val("Zero"),
    zeroTemperature: val("Zero Temperature"),
    zeroTime: val("Zero Time"),
    gainTrim: val("Gain Trim"),
    vout: val("Voltage"),
  };
}

// Everything the page shows, worked out from the store at time now (ms, as passed to receive).
function readYoke(store, now) {
  const val = (name) => store.get(name)?.value;
  const faultText = val("Fault Text");
  const faults = faultText == null || faultText === "OK" ? [] : faultText.split("; ");
  const notZeroed = wayList(val("Not Zeroed"));
  const overRange = waysWith(faults, "over range");
  const ways = Array.from({ length: WAYS }, (_, i) => readWay(store, i + 1, overRange, notZeroed));

  const status =
    faultText == null ? { kind: "waiting" }
    : faults.length && !(faults.length === 1 && faults[0] === "No supply") ? { kind: "fault", faults }
    : faults.length ? { kind: "nosupply" }
    : notZeroed.length ? { kind: "install", zeroed: WAYS - notZeroed.length }
    : { kind: "ok" };

  let install = null;
  if (notZeroed.length) {
    const unzeroed = ways.filter((w) => w?.unzeroed);
    const uptime = store.get("Uptime");
    install = {
      pull: unzeroed.filter((w) => w.live).map((w) => w.n),
      zeroing: unzeroed.filter((w) => !w.live).map((w) => w.n),
      endsInS: uptime?.value == null ? null
        : Math.max(0, Math.round(INSTALL_S - uptime.value - (now - uptime.at) / 1000)),
    };
  }

  return {
    ways, status, install,
    liveWays: ways.filter((w) => w?.live).length,
    totalCurrent: ways.filter(flowing).reduce((a, w) => a + (w.current || 0), 0),
    panelVoltage: val("Panel Voltage"),
    temperatures: { odd: val("Temperature: Odd Arm"), chin: val("Temperature: Chin"), even: val("Temperature: Even Arm") },
    system: { wifi: val("Wi-Fi Signal"), esp32: val("Temperature: ESP32"), firmware: val("Firmware"), uptime: val("Uptime") },
  };
}

