// </board-art>

// The art's own styles, which travel inside its image. Nothing in it moves: a way blinks by a
// layer of the art with it dimmed (.dim) showing over the art with it lit.
const ART_CSS = ".outline{fill:var(--mask);stroke:var(--mask-edge);stroke-width:.25}.cu-ring{fill:var(--copper);stroke:var(--copper)}.cu-parts{fill:var(--cu-parts);stroke:var(--cu-parts);opacity:.7}.pad{fill:var(--hasl);stroke:var(--hasl)}.via{stroke:#5E656C}.hole{fill:var(--hole)}.comp{fill:none;stroke:var(--comp);stroke-width:.15}.silk{fill:var(--silk);stroke:none}g[id^=w]{--lit:var(--copper)}g[id^=w].live{--lit:var(--glow)}g[id^=w].live :is(.cu-ring,.cu-parts){opacity:var(--k)!important}g[id^=w].unz{--lit:var(--pink)}g[id^=w].blown,g[id^=w].range{--lit:var(--red)}g[id^=w]:is(.live,.unz,.blown,.range) :is(.cu-ring,.cu-parts){fill:var(--lit);stroke:var(--lit);opacity:1}g[id^=w]:is(.live,.unz,.blown,.range) .pad{fill:color-mix(in srgb,var(--lit) 55%,var(--hasl))}g[id^=w].dim{opacity:.35}";
// The page's colours the art uses: an image can't read the page's custom properties.
const ART_VARS = [...new Set([...ART_CSS.matchAll(/var\((--[\w-]+)/g)].map(([, v]) => v))].filter((v) => v !== "--lit" && v !== "--k");

// ── View ──

// connected starts true so the warning shows only once /events has failed.
const ui = { yoke: null, open: null, openPos: "", gap: 0, theme: "dark", themePref: null, connected: true };

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const fmt = (x, d = 1, unit = "") => (x == null || Number.isNaN(+x) ? "–" : `${(+x).toFixed(d)}${unit}`);
const duration = (s) => (s == null ? "–" : s < 3600 ? `${Math.round(s / 60)} min` : s < 172800 ? `${Math.round(s / 3600)} h` : `${Math.round(s / 86400)} d`);
const energy = (wh) => (wh == null ? "–" : Math.abs(wh) >= 1000 ? fmt(wh / 1000, 2, " kWh") : fmt(wh, 1, " Wh"));
const list = (ns) => ns.join(", ").replace(/, (\d+)$/, " and $1");
const fullness = (w) => Math.min(1, Math.abs(w?.current || 0) / OVER_RANGE_A);
const faulty = (w) => w.state === "blown" || w.state === "range";
// A way's copper: red for a fault, blinking pink while live and unzeroed, amber while live.
const lit = (w) => (!w ? "" : faulty(w) ? w.state : w.unzeroed ? (w.live ? "unz" : "") : w.live ? "live" : "");
const STATE_WORD = { live: "Live", empty: "Empty", blown: "Blown", range: "Over range" };

// On a narrow screen each row of ways gets a gap (mm) of extra height, stretched only across thin
// bands where copper runs vertically, so rings, pads and silk keep their shape.
const VB = BOARD.viewBox;
const CUT_H = 0.2;
const CUTS = [
  [BOARD.ways[1].screw[1] - 6.0, 0.5],
  ...[1, 3, 5, 7, 9, 11].flatMap((n) => [[BOARD.ways[n].screw[1] + 5.4, 0.5], [BOARD.ways[n].screw[1] + 7.7, 0.5]]),
];
const PANEL_Y = 28; // panel voltage, in the opening's foot
const TEMPS_Y = 39.4; // the three temperatures, below it
const gapFor = (width) => Math.max(0, Math.min(7, Math.round((600 - width) / 15) / 2));
const height = () => VB.height + CUTS.reduce((a, [, f]) => a + f * ui.gap, 0);
const M = (y) => y + CUTS.reduce((a, [c, f]) => a + (y > c + CUT_H / 2 ? f * ui.gap : 0), 0);
const X = (x) => ((x - VB.x) / VB.width) * 100;
const Y = (y) => ((M(y) - VB.y) / height()) * 100;

const SUN = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M5.3 18.7l1.6-1.6M17.1 6.9l1.6-1.6"/></svg>';
const MOON = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg>';

function head(y) {
  const s = y.status;
  const nbsp = (t) => esc(t).replace(/ (°C|A)\b/g, " $1");
  const [cls, title, act] =
    s.kind === "waiting" ? ["", "<span>Connecting…</span>", ""]
    : s.kind === "fault" ? ["bad", s.faults.map((f) => `<span>${nbsp(f)}</span>`).join(""), '<button class="clear" data-press="Clear Faults">Clear faults</button><span>A fault whose cause is still there comes back.</span>']
    : s.kind === "nosupply" ? ["", "<span>No supply</span>", "<span>Running on USB.</span>"]
    : s.kind === "install" ? ["", `<span>${s.zeroed} of ${WAYS} ways zeroed</span>`, ""]
    : ["ok", "<span>All OK</span>", `<span>${fmt(y.totalCurrent, 1, " A")} across ${y.liveWays} live way${y.liveWays === 1 ? "" : "s"}</span>`];
  const next = ui.theme === "dark" ? "light" : "dark";
  return `<div class="head"><div class="hrow"><h1 class="${cls}">${title}</h1>
    <button class="theme" data-theme-toggle aria-label="Switch to ${next} mode" title="Switch to ${next} mode">${ui.theme === "dark" ? SUN : MOON}</button></div>
    ${act ? `<div class="act">${act}</div>` : ""}
    ${ui.connected ? "" : '<div class="lost">Not connected to the yoke. Retrying…</div>'}
    ${installNote(y.install)}</div>`;
}

function installNote(inst) {
  if (!inst) return "";
  const { pull, zeroing, endsInS } = inst;
  const what = pull.length ? `Pull or move the fuse on way${pull.length > 1 ? "s" : ""} ${list(pull)}.` : "Leave the fuses as they are.";
  const dead = zeroing.length ? `${zeroing.length > 1 ? "Ways" : "Way"} ${list(zeroing)} ${zeroing.length > 1 ? "are" : "is"} dead and zeroing. ` : "";
  const ends = endsInS == null ? "Install mode ends 1 h after boot."
    : endsInS > 0 ? `Install mode ends in ${Math.ceil(endsInS / 60)} min.`
    : "Install mode has ended, but a way still zeros once it has been dead for 15 s.";
  return `<div class="install"><b>${what}</b><span>${dead}${ends}</span></div>`;
}

function reading(w, n) {
  const p = BOARD.ways[n];
  const odd = n % 2 === 1;
  const note = !w ? '<div class="p">No reading</div>'
    : faulty(w) ? `<div class="p bad">${STATE_WORD[w.state]}</div>`
    : w.unzeroed ? `<div class="p warn">${w.live ? "Pull to zero" : "Zeroing"}</div>`
    : flowing(w) ? `<div class="p">${fmt(w.power, 0, " W")}</div>`
    : '<div class="p">Empty</div>';
  const pos = odd ? `left:${X(p.tip[0] + 2.2)}%` : `right:${100 - X(p.tip[0] - 2.2)}%`;
  return `<div class="rd ${odd ? "o" : "e"}" style="${pos};top:${Y(p.screw[1])}%">
    <div class="i"><span class="n">${n}</span><span>${flowing(w) ? `${fmt(w.current, 1)}<small>A</small>` : "–"}</span></div>${note}
    <div class="bar"><i style="width:${flowing(w) ? Math.max(2, fullness(w) * 100) : 0}%"></i></div></div>`;
}

// What lies over the art, as plain HTML so nothing on the board is inline SVG: each way's tap
// target, then the LEDs.
function overlay(y) {
  const out = [];
  for (let n = 1; n <= WAYS; n++) {
    const yy = BOARD.ways[n].screw[1];
    out.push(`<div class="hit${ui.open === n ? " sel" : ""}" data-way="${n}" tabindex="0" role="button" aria-label="Way ${n}" style="left:${X(n % 2 ? VB.x + 0.5 : 0.5)}%;top:${Y(yy - 6.4)}%;width:${((VB.width / 2 - 1) / VB.width) * 100}%;height:${Y(yy + 6.4) - Y(yy - 6.4)}%"></div>`);
  }
  // The red LED, as the yoke shows it: steady for a fault, slow blink in install mode with a live way unzeroed.
  const led = y.status.kind === "fault" ? "on" : y.install?.pull.length && y.install.endsInS !== 0 ? "on slow" : "";
  out.push(`<span class="led ${led}" title="Red LED" style="left:${X(BOARD.faultLed[0])}%;top:${Y(BOARD.faultLed[1])}%"></span>`,
    `<span class="led sled" style="left:${X(BOARD.statusLed[0])}%;top:${Y(BOARD.statusLed[1])}%"></span>`);
  return out.join("");
}
// A way's popover. It floats over the board, so nothing moves, and it is always in the DOM, so
// opening it doesn't shift the stage's children and restart their animations.
function popover(y) {
  const w = ui.open && y.ways[ui.open - 1];
  if (!w) return '<div class="pop" hidden></div>';
  const z = !w.unzeroed; // the zero diagnostics are the way's own
  return `<div class="pop ${!faulty(w) && w.unzeroed ? "unz" : w.state}" style="${ui.openPos}" role="dialog" aria-label="Way ${w.n}">
    <button class="x" data-close aria-label="Close">×</button>
    <div class="ph"><h2>Way ${w.n}</h2><span>${STATE_WORD[w.state]}${w.unzeroed ? ", unzeroed" : ""}</span></div>
    <div class="big">${flowing(w) ? `${fmt(w.current, 2)}<small>A</small>` : "–"}</div>
    <dl><dt>Power</dt><dd>${flowing(w) ? fmt(w.power, 0, " W") : "–"}</dd><dt>Energy</dt><dd>${energy(w.energy)}</dd>
      <dt>Zero</dt><dd>${z ? fmt(w.zero, 1, " mV") : "Borrowed"}</dd><dt>Zero at</dt><dd>${z ? fmt(w.zeroTemperature, 0, " °C") : "–"}</dd>
      <dt>Zeroed</dt><dd>${z && w.zeroTime != null ? `${duration(w.zeroTime)} after boot` : "–"}</dd><dt>Gain trim</dt><dd>${fmt(w.gainTrim, 3)}</dd>
      <dt>Vout</dt><dd>${fmt(w.vout, 3, " V")}</dd><dt>Arm</dt><dd>${w.n % 2 ? "Odd" : "Even"}</dd></dl></div>`;
}

function page(y) {
  const t = y.temperatures;
  const s = y.system;
  const op = BOARD.opening;
  return `<div class="wrap">${head(y)}
  <div class="case"><span class="boss b1"></span><span class="boss b2"></span><span class="boss b3"></span><span class="boss b4"></span>
   <div class="mould"><span>↑</span><span>up</span><span>↑</span></div>
   <div class="stage" style="aspect-ratio:${VB.width}/${height()}">
    <div class="art" data-static></div>
    <div class="frost"></div>
    <div class="pane" style="left:${X(op.x)}%;top:${Y(op.y)}%;width:${(op.width / VB.width) * 100}%;height:${Y(op.y + op.height) - Y(op.y)}%"></div>
    <div class="ov">${overlay(y)}</div>
    ${y.ways.map((w, i) => reading(w, i + 1)).join("")}
    <div class="panelv" style="top:${Y(PANEL_Y)}%"><b>${fmt(y.panelVoltage, 2, " V")}</b><span>Panel · ${fmt(y.totalCurrent, 1, " A")} total</span></div>
    <div class="temps" style="top:${Y(TEMPS_Y)}%"><span><em>Odd</em>${fmt(t.odd, 0, " °C")}</span><span><em>Chin</em>${fmt(t.chin, 0, " °C")}</span><span><em>Even</em>${fmt(t.even, 0, " °C")}</span></div>
    ${popover(y)}
   </div>
  </div>
  <div class="sys"><span>Wi-Fi ${fmt(s.wifi, 0, " dBm")}</span><span>ESP32 ${fmt(s.esp32, 0, " °C")}</span><span>Up ${duration(s.uptime)}</span><span>${esc(s.firmware ?? "")}</span></div>
  <div class="sys"><button data-press="Restart">Restart</button><button class="danger" data-press="Factory Reset">Factory reset</button></div>
  </div>`;
}

// The art is an SVG image, not inline SVG: Firefox rasterises inline SVG on the CPU again at every
// zoom step, and the art is big. One image document holds the whole art; each band is an <img>
// of its own slice, so a stretched band is drawn at its own size.
// The art is rebuilt only when what it shows changes: the gap, the theme, or a way's state or
// brightness step.

// A way's brightness in quarter steps, held until the reading is well past the next one, so a
// reading on the boundary doesn't rebuild the art every second.
const artSteps = [];
function artStep(w, n) {
  const s = Math.sqrt(fullness(w)) * 4;
  if (artSteps[n] == null || Math.abs(s - artSteps[n]) > 0.6) artSteps[n] = Math.round(s);
  return artSteps[n] / 4;
}

// Blinks, as quarters of a 1 s cycle in which a state's ways are off: unzeroed blink every 1 s,
// over range every 0.5 s. Each quarter with ways off is a layer of the art with them dimmed, over
// the art with every way on; the layer's opacity steps through its quarters (page.css, .q*).
const BLINK_OFF = { unz: [2, 3], range: [1, 3] };
function artLayers(y) {
  const layers = new Map();
  for (const q of [1, 2, 3]) {
    const off = Object.keys(BLINK_OFF).filter((s) => BLINK_OFF[s].includes(q) && y.ways.some((w) => lit(w) === s)).join(" ");
    if (off) layers.set(off, (layers.get(off) || "") + q);
  }
  return [...layers].map(([off, qs]) => ({ off: off.split(" "), cls: `q${qs}` }));
}

function artSvg(y, colours, off) {
  let art = ART;
  let ks = "";
  for (let n = 1; n <= WAYS; n++) {
    const w = y.ways[n - 1];
    const cls = lit(w);
    art = art.replace(`<g id="w${n}">`, `<g id="w${n}" class="${cls}${off.includes(cls) ? " dim" : ""}">`);
    ks += `#w${n}{--k:${(0.35 + 0.65 * artStep(w, n)).toFixed(2)}}`;
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VB.x} ${VB.y} ${VB.width} ${VB.height}"><style>svg{${colours}}${ART_CSS}${ks}</style><g stroke-linecap="round" stroke-linejoin="round">${art}</g></svg>`;
}

function artBands() {
  const bands = [];
  let y0 = VB.y;
  for (const [c, f] of CUTS) {
    bands.push([y0, c, 0], [c, c + CUT_H, f * ui.gap]);
    y0 = c + CUT_H;
  }
  bands.push([y0, VB.y + VB.height, 0]);
  return bands;
}

let artKey = "";
let artUrls = [];
function paintArt(y) {
  const page = getComputedStyle(document.documentElement);
  const colours = ART_VARS.map((v) => `${v}:${page.getPropertyValue(v).trim()}`).join(";");
  const key = `${ui.gap}|${colours}` + y.ways.map((w, i) => `|${lit(w)}${artStep(w, i + 1)}`).join("");
  if (key === artKey) return;
  artKey = key;
  const layers = artLayers(y);
  const urls = [[], ...layers.map((l) => l.off)].map((off) => URL.createObjectURL(new Blob([artSvg(y, colours, off)], { type: "image/svg+xml" })));
  // Swapped in once decoded, so the art never blanks between versions. Every layer is made anew
  // at once, so their blinks start together.
  Promise.all(urls.map((u) => Object.assign(new Image(), { src: u }).decode().catch(() => {}))).then(() => {
    if (artKey !== key) return urls.forEach((u) => URL.revokeObjectURL(u));
    artUrls.forEach((u) => URL.revokeObjectURL(u));
    artUrls = urls;
    const bands = artBands();
    document.querySelector(".art").innerHTML = urls.map((u, i) => `<div class="layer ${i ? layers[i - 1].cls : ""}">${bands.map(([a, b, g]) => `<img alt="" src="${u}#svgView(viewBox(${VB.x},${a},${VB.width},${b - a});preserveAspectRatio(none))" style="height:${((b - a + g) / height()) * 100}%">`).join("")}</div>`).join("");
  });
}

// Patch the live DOM to match the new markup rather than replacing it, so running animations
// carry on across updates instead of restarting.
function morph(a, b) {
  if (a.nodeType !== b.nodeType || a.nodeName !== b.nodeName) return a.replaceWith(b.cloneNode(true));
  if (a.nodeType === 3) {
    if (a.nodeValue !== b.nodeValue) a.nodeValue = b.nodeValue;
    return;
  }
  if (a.nodeType !== 1) return;
  if (a.hasAttribute("data-static") && a.firstChild) return;
  for (const { name } of [...a.attributes]) if (!b.hasAttribute(name)) a.removeAttribute(name);
  for (const { name, value } of [...b.attributes]) if (a.getAttribute(name) !== value) a.setAttribute(name, value);
  const ac = [...a.childNodes];
  const bc = [...b.childNodes];
  bc.forEach((node, i) => (ac[i] ? morph(ac[i], node) : a.appendChild(node.cloneNode(true))));
  ac.slice(bc.length).forEach((node) => node.remove());
}

const store = newStore();
const tpl = typeof document === "undefined" ? null : document.createElement("template");
let pending = false;

function render() {
  pending = false;
  ui.gap = gapFor(innerWidth);
  ui.yoke = readYoke(store, Date.now());
  const app = document.getElementById("app");
  tpl.innerHTML = page(ui.yoke);
  const next = tpl.content.firstElementChild;
  if (app.firstElementChild) morph(app.firstElementChild, next);
  else app.append(next);
  paintArt(ui.yoke);
}
function schedule() {
  if (!pending) {
    pending = true;
    requestAnimationFrame(render);
  }
}

function openWay(n, el) {
  if (ui.open === n) return closeWay();
  const stage = el.closest(".stage").getBoundingClientRect();
  const r = el.getBoundingClientRect();
  // Below the way, or above it for the lower rows, so it stays on the board.
  ui.openPos = r.top - stage.top > stage.height * 0.5 ? `bottom:${stage.bottom - r.top + 4}px` : `top:${r.bottom - stage.top + 4}px`;
  ui.open = n;
  render();
}
function closeWay() {
  ui.open = null;
  render();
}

function press(name) {
  if (name !== "Clear Faults" && !confirm(`${name} the yoke?`)) return;
  fetch(`/button/${encodeURIComponent(name)}/press`, { method: "POST" });
}

// The theme follows the phone until the button is pressed; then that choice is kept, on that phone.
function applyTheme() {
  ui.theme = ui.themePref || (matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
  document.documentElement.dataset.theme = ui.theme;
}
function toggleTheme() {
  ui.themePref = ui.theme === "dark" ? "light" : "dark";
  try {
    localStorage.setItem("theme", ui.themePref);
  } catch {}
  applyTheme();
  render();
}

function boot() {
  document.documentElement.lang = "en-GB";
  document.title = "Blade Reader";
  document.querySelector("esp-app")?.remove();
  const app = document.createElement("main");
  app.id = "app";
  document.body.append(app);

  try {
    ui.themePref = localStorage.getItem("theme");
  } catch {}
  applyTheme();
  matchMedia("(prefers-color-scheme: light)").addEventListener("change", () => {
    applyTheme();
    render();
  });

  addEventListener("click", (e) => {
    const t = e.target.closest("[data-way],[data-press],[data-close],[data-theme-toggle]");
    if (t?.dataset.way) openWay(+t.dataset.way, t);
    else if (t?.dataset.press) press(t.dataset.press);
    else if (t?.hasAttribute("data-close")) closeWay();
    else if (t?.hasAttribute("data-theme-toggle")) toggleTheme();
    else if (ui.open && !e.target.closest(".pop")) closeWay();
  });
  addEventListener("keydown", (e) => {
    if (e.key === "Escape" && ui.open) closeWay();
    const t = e.target.closest?.("[data-way]");
    if (t && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      openWay(+t.dataset.way, t);
    }
  });
  addEventListener("resize", () => {
    if (gapFor(innerWidth) !== ui.gap) schedule();
  });
  // The install countdown moves between Uptime updates.
  setInterval(schedule, 10000);

  const events = new EventSource("/events");
  events.addEventListener("open", () => {
    ui.connected = true;
    schedule();
  });
  events.addEventListener("error", () => {
    ui.connected = false;
    schedule();
  });
  // Each way publishes on its own clock, so states trickle in across the second: gather them into
  // one render rather than repainting the page for each.
  let gathering = 0;
  events.addEventListener("state", (m) => {
    receive(store, JSON.parse(m.data), Date.now());
    gathering ||= setTimeout(() => {
      gathering = 0;
      schedule();
    }, 250);
  });
  render();
}

if (typeof document !== "undefined") boot();
